using System.Reflection;
using System.Reflection.Metadata;
using System.Reflection.PortableExecutable;
using PaymentAuthorization.Application;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.ArchitectureTest;

public sealed class LayerRulesTests
{
    private static readonly string[] TechnicalNamespaces =
    [
        "System.IO", "System.Net", "System.Data", "System.Text.Json",
        "System.Xml", "System.Diagnostics", "System.Security.Cryptography",
        "System.Reflection", "Microsoft",
    ];

    private static readonly Assembly Domain = typeof(Money).Assembly;
    private static readonly Assembly Application = typeof(IPaymentGateway).Assembly;
    private static readonly Assembly Infrastructure = typeof(HttpPaymentGateway).Assembly;

    [Fact]
    public void Domain_depends_on_no_other_layer()
    {
        AssertNoReferences(Domain, Application, Infrastructure);
    }

    [Fact]
    public void Application_does_not_depend_on_infrastructure()
    {
        AssertNoReferences(Application, Infrastructure);
    }

    [Theory]
    [MemberData(nameof(BusinessAssemblies))]
    public void Business_code_does_not_use_technical_details(Assembly assembly)
    {
        var offenders = TypeReferences(assembly)
            .Where(t => TechnicalNamespaces.Any(n => t.Namespace == n || t.Namespace.StartsWith(n + ".")))
            .Select(t => $"{t.Namespace}.{t.Name}")
            .Distinct()
            .Order()
            .ToList();

        Assert.True(offenders.Count == 0,
            $"{assembly.GetName().Name} must stay free of technical details, but uses: {string.Join(", ", offenders)}");
    }

    public static TheoryData<Assembly> BusinessAssemblies() => new() { Domain, Application };

    private static void AssertNoReferences(Assembly from, params Assembly[] forbidden)
    {
        var referenced = from.GetReferencedAssemblies().Select(a => a.Name).ToHashSet();
        var offenders = forbidden.Select(a => a.GetName().Name!).Where(referenced.Contains).ToList();
        Assert.True(offenders.Count == 0,
            $"{from.GetName().Name} must not reference: {string.Join(", ", offenders)}");
    }

    private static IEnumerable<(string Namespace, string Name)> TypeReferences(Assembly assembly)
    {
        using var stream = File.OpenRead(assembly.Location);
        using var pe = new PEReader(stream);
        var reader = pe.GetMetadataReader();
        foreach (var handle in reader.TypeReferences)
        {
            var type = reader.GetTypeReference(handle);
            yield return (reader.GetString(type.Namespace), reader.GetString(type.Name));
        }
    }
}
